contract PRIVATE_ETH_CELL
{
mapping (address=>uint256) public balances;

uint public MinSum;

LogFile Log;

bool intitalized;

function SetMinSum(uint _val)
public
{
require(!intitalized);
MinSum = _val;
}

function SetLogFile(address _log)
public
{
require(!intitalized);
Log = LogFile(_log);
}

function Initialized()
public
{
intitalized = true;
}

function Deposit()
public
payable
{
balances[msg.sender]+= msg.value;
